{
  "steps": [
    {
      "id": "s1",
      "agent_id": "researcher",
      "description": "Perform market and literature research on grid-scale energy storage technologies (battery chemistries such as Li-ion and flow batteries, pumped hydro, compressed air, hydrogen/Power-to-X, thermal storage, flywheels, ultra-capacitors). For each technology collect source-cited, recent (preferably last 5 years) datapoints into a CSV with these columns: technology, source_url, observation_date, capital_cost_usd_per_kw, capital_cost_usd_per_kwh, typical_duration_hours, round_trip_efficiency_pct, typical_project_capacity_mw, typical_project_storage_mwh, opex_usd_per_year_per_mw_or_per_mwh (specify units), lifespan_years, lead_time_months, notes. Include ranges where applicable and at least 2 authoritative sources per major technology. Save as market_research.csv.",
      "dependencies": [],
      "produces": "market_research.csv",
      "consumes": [],
      "rationale": "External market data and citations are required to compare cost and duration.",
      "needs_tools": [
        "web_search"
      ]
    },
    {
      "id": "s2",
      "agent_id": "data_analyst",
      "description": "Ingest market_research.csv, normalize units, and compute comparable metrics: capital_cost_usd_per_kwh, capital_cost_usd_per_kw, levelized_cost_per_kwh_cycle (LCOC) using standard assumptions (document assumptions), effective usable duration (hours), and lifecycle cost estimates. Produce a cleaned quantitative table and summary with: median and range by technology, cost vs duration scatter, and a short sensitivity analysis for duration and capital cost (showing effect on LCOC). Create a CSV cost_duration_analysis.csv with fields: technology, median_capex_usd_per_kwh, median_capex_usd_per_kw, median_duration_hours, median_efficiency_pct, median_lcoc_usd_per_kwh, capex_range_usd_per_kwh, notes_assumptions, source_summary. Save outputs and a 1-paragraph numeric summary in the CSV or accompanying text column.",
      "dependencies": [
        "s1"
      ],
      "produces": "cost_duration_analysis.csv",
      "consumes": [
        "market_research.csv"
      ],
      "rationale": "Quantitative normalization and LCOC calculation require data-analysis skills and runtime tools.",
      "needs_tools": [
        "read_file",
        "terminal"
      ]
    },
    {
      "id": "s3",
      "agent_id": "creative",
      "description": "Draft an executive briefing (executive_briefing.md) of ~1–2 pages that: 1) summarizes scope and methods, 2) presents the key quantitative comparison (one concise table pulled from cost_duration_analysis.csv), 3) gives a clear recommendation (best choice for short-duration <4h, medium 4–12h, long >12h and a single prioritized recommendation for immediate action), 4) explains rationale, key risks/uncertainties, and 3 recommended next steps with rough cost/time estimates. Cite the cost_duration_analysis.csv and include an appendix line pointing to market_research.csv. Make the recommendation actionable for executives.",
      "dependencies": [
        "s2"
      ],
      "produces": "executive_briefing.md",
      "consumes": [
        "cost_duration_analysis.csv"
      ],
      "rationale": "An executive-facing briefing requires a specialist who writes clear markdown reports.",
      "needs_tools": [
        "read_file",
        "write_file"
      ]
    }
  ]
}
